469	  /**
470	   * Indicates whether {@code c} is one of the twenty-six uppercase ASCII alphabetic characters
471	   * between {@code 'A'} and {@code 'Z'} inclusive. All others (including non-ASCII characters)
472	   * return {@code false}.
473	   */
474	  public static boolean isUpperCase(char c) {
475	    return (c >= 'A') && (c <= 'Z');
476	  }
