478	  /**
479	   * Truncates the given character sequence to the given maximum length. If the length of the
480	   * sequence is greater than {@code maxLength}, the returned string will be exactly {@code
481	   * maxLength} chars in length and will end with the given {@code truncationIndicator}. Otherwise,
482	   * the sequence will be returned as a string with no changes to the content.
483	   *
484	   * <p>Examples:
485	   *
486	   * {@snippet :
487	   * Ascii.truncate("foobar", 7, "..."); // returns "foobar"
488	   * Ascii.truncate("foobar", 5, "..."); // returns "fo..."
489	   * }
490	   *
491	   * <p><b>Note:</b> This method <i>may</i> work with certain non-ASCII text but is not safe for use
492	   * with arbitrary Unicode text. It is mostly intended for use with text that is known to be safe
493	   * for use with it (such as all-ASCII text) and for simple debugging text. When using this method,
494	   * consider the following:
495	   *
496	   * <ul>
497	   *   <li>it may split surrogate pairs
498	   *   <li>it may split characters and combining characters
499	   *   <li>it does not consider word boundaries
500	   *   <li>if truncating for display to users, there are other considerations that must be taken
501	   *       into account
502	   *   <li>the appropriate truncation indicator may be locale-dependent
503	   *   <li>it is safe to use non-ASCII characters in the truncation indicator
504	   * </ul>
505	   *
506	   * @throws IllegalArgumentException if {@code maxLength} is less than the length of {@code
507	   *     truncationIndicator}
508	   * @since 16.0
509	   */
510	  public static String truncate(CharSequence seq, int maxLength, String truncationIndicator) {
511	    checkNotNull(seq);
512	
513	    // length to truncate the sequence to, not including the truncation indicator
514	    int truncationLength = maxLength - truncationIndicator.length();
515	
516	    // in this worst case, this allows a maxLength equal to the length of the truncationIndicator,
517	    // meaning that a string will be truncated to just the truncation indicator itself
518	    checkArgument(
519	        truncationLength >= 0,
520	        "maxLength (%s) must be >= length of the truncation indicator (%s)",
521	        maxLength,
522	        truncationIndicator.length());
523	
524	    if (seq.length() <= maxLength) {
525	      String string = seq.toString();
526	      if (string.length() <= maxLength) {
527	        return string;
528	      }
529	      // if the length of the toString() result was > maxLength for some reason, truncate that
530	      seq = string;
531	    }
532	
533	    return new StringBuilder(maxLength)
534	        .append(seq, 0, truncationLength)
535	        .append(truncationIndicator)
536	        .toString();
537	  }
