539	  private static String convertCase(CharSequence chars, boolean toLowerCase) {
540	    if (chars instanceof String) {
541	      return convertCase((String) chars, toLowerCase);
542	    }
543	    char[] newChars = new char[chars.length()];
544	    for (int i = 0; i < newChars.length; i++) {
545	      newChars[i] = convertCase(chars.charAt(i), toLowerCase);
546	    }
547	    return String.valueOf(newChars);
548	  }
549	
550	  private static String convertCase(String string, boolean toLowerCase) {
551	    int length = string.length();
552	    for (int i = 0; i < length; i++) {
553	      if (needsCaseConversion(string.charAt(i), toLowerCase)) {
554	        char[] chars = string.toCharArray();
555	        for (; i < length; i++) {
556	          char c = chars[i];
557	          if (needsCaseConversion(c, toLowerCase)) {
558	            chars[i] = convertCase(c, toLowerCase);
559	          }
560	        }
561	        return String.valueOf(chars);
562	      }
563	    }
564	    return string;
565	  }
566	
567	  private static boolean needsCaseConversion(char c, boolean toLowerCase) {
568	    return toLowerCase ? isUpperCase(c) : isLowerCase(c);
569	  }
570	
571	  private static char convertCase(char c, boolean toLowerCase) {
572	    return needsCaseConversion(c, toLowerCase) ? (char) (c ^ CASE_MASK) : c;
573	  }
