575	  /**
576	   * Indicates whether the contents of the given character sequences {@code s1} and {@code s2} are
577	   * equal, ignoring the case of any ASCII alphabetic characters between {@code 'a'} and {@code 'z'}
578	   * or {@code 'A'} and {@code 'Z'} inclusive.
579	   *
580	   * <p>This method is significantly faster than {@link String#equalsIgnoreCase} and should be used
581	   * in preference if at least one of the parameters is known to contain only ASCII characters.
582	   *
583	   * <p>Note however that this method does not always behave identically to expressions such as:
584	   *
585	   * <ul>
586	   *   <li>{@code string.toUpperCase().equals("UPPER CASE ASCII")}
587	   *   <li>{@code string.toLowerCase().equals("lower case ascii")}
588	   * </ul>
589	   *
590	   * <p>due to case-folding of some non-ASCII characters (which does not occur in {@link
591	   * String#equalsIgnoreCase}). However in almost all cases that ASCII strings are used, the author
592	   * probably wanted the behavior provided by this method rather than the subtle and sometimes
593	   * surprising behavior of {@code toUpperCase()} and {@code toLowerCase()}.
594	   *
595	   * @since 16.0
596	   */
597	  public static boolean equalsIgnoreCase(CharSequence s1, CharSequence s2) {
598	    // Calling length() is the null pointer check (so do it before we can exit early).
599	    int length = s1.length();
600	    if (s1 == s2) {
601	      return true;
602	    }
603	    if (length != s2.length()) {
604	      return false;
605	    }
606	    for (int i = 0; i < length; i++) {
607	      char c1 = s1.charAt(i);
608	      char c2 = s2.charAt(i);
609	      if (c1 == c2) {
610	        continue;
611	      }
612	      int alphaIndex = getAlphaIndex(c1);
613	      // This was also benchmarked using '&' to avoid branching (but always evaluate the rhs),
614	      // however this showed no obvious improvement.
615	      if (alphaIndex < 26 && alphaIndex == getAlphaIndex(c2)) {
616	        continue;
617	      }
618	      return false;
619	    }
620	    return true;
621	  }
622	
623	  /**
624	   * Returns the non-negative index value of the alpha character {@code c}, regardless of case. Ie,
625	   * 'a'/'A' returns 0 and 'z'/'Z' returns 25. Non-alpha characters return a value of 26 or greater.
626	   */
627	  private static int getAlphaIndex(char c) {
628	    // Fold upper-case ASCII to lower-case and make zero-indexed and unsigned (by casting to char).
629	    return (char) ((c | CASE_MASK) - 'a');
630	  }
